  'learn-primera-app': learnBase + 'build-mobile-and-desktop-apps/',
  'learn-layouts': learnBase + 'customize-xaml-pages-layout/',
  'learn-xaml': learnBase + 'create-user-interface-xaml/',
  'learn-multipagina': learnBase + 'create-multi-page-apps/',
