export function enrichLessons(lessons) {
  for (const l of lessons) {
    const guide = lessonGuide[l.id];
    if (guide) { l.guide = guide; l.quizzes.push(...extraQuestions[l.id]); }
    else l.guide = { prerequisites:l.unit==='UD2'?['Conceptos de XAML y eventos de las lecciones iniciales.']:['XAML, controles y diccionarios de recursos.'], flow:l.practice.solution, steps:l.practice.steps.map((title,i)=>[title,l.sections[Math.min(i,l.sections.length-1)].paragraphs.join(' ')]), packageId:l.id };
  }
}

